window.addEventListener("scroll",function(){let e=document.querySelector(".navbar"),s=document.querySelector("nav");window.scrollY>20?(e.classList.remove("transparent"),e.classList.add("scrolled"),s.classList.add("scrolled-nav")):(e.classList.add("transparent"),e.classList.remove("scrolled"),s.classList.remove("scrolled-nav"));let l=document.querySelector(".header-whatsapp"),t=document.querySelector(".fixed-whatsapp"),i=window.scrollY;document.querySelector(".placeholder-header").offsetHeight,i>100?(t.style.opacity="1",t.style.visibility="visible",l&&(l.style.opacity="0",l.style.visibility="hidden")):(t.style.opacity="0",t.style.visibility="hidden",l&&(l.style.opacity="1",l.style.visibility="visible"))});